lor:#9a3412}@media(max-width:700px){.qrf-grid,.qrf-summary{grid-template-columns:1fr 1fr}.qrf-body{padding:16px}}@media(max-width:450px){.qrf-grid,.qrf-summary{grid-template-columns:1fr}}
