<div class="qrf" id="quality-report-fields">
 <section class="qrf-section"><div class="qrf-head"><div class="qrf-step">01</div><div><h4>Report Information</h4><p>Reference, linked inspection and reporting period</p></div></div><div class="qrf-body"><div class="qrf-grid">
  <div class="qrf-field"><label for="report_number">Report Number <span class="qrf-required">*</span></label><input id="report_number" name="report_number" required value="{{ old('report_number', $report->report_number ?? '') }}" placeholder="e.g. QR-2026-001">@error('report_number')<div class="qrf-error">{{ $message }}</div>@enderror</div>
  <div class="qrf-field"><label for="inspection_id">Linked Inspection</label><select id="inspection_id" name="inspection_id"><option value="">Select inspection</option>@foreach(($inspections ?? collect()) as $option)<option value="{{ $option->id }}" @selected((string) old('inspection_id', $report->inspection_id ?? '') === (string) $option->id)>Inspection #{{ $option->id }}@if($option->inspection_type ?? null) — {{ ucwords(str_replace('_',' ', $option->inspection_type)) }}@endif</option>@endforeach</select>@error('inspection_id')<div class="qrf-error">{{ $message }}</div>@enderror</div>
  <div class="qrf-field"><label for="report_period_start">Period Start</label><input type="date" id="report_period_start" name="report_period_start" value="{{ old('report_period_start', isset($report->report_period_start) ? \Illuminate\Support\Carbon::parse($report->report_period_start)->format('Y-m-d') : '') }}">@error('report_period_start')<div class="qrf-error">{{ $message }}</div>@enderror</div>
  <div class="qrf-field"><label for="report_period_end">Period End</label><input type="date" id="report_period_end" name="report_period_end" value="{{ old('report_period_end', isset($report->report_period_end) ? \Illuminate\Support\Carbon::parse($report->report_period_end)->format('Y-m-d') : '') }}">@error('report_period_end')<div class="qrf-error">{{ $message }}</div>@enderror</div>
 </div></div></section>
 <section class="qrf-section"><div class="qrf-head navy"><div class="qrf-step">02</div><div><h4>Inspection Results & Quality Performance</h4><p>Record accepted, rejected and total inspected quantities</p></div></div><div class="qrf-body"><div class="qrf-grid">
  <div class="qrf-field"><label for="total_inspected">Total Inspected</label><input type="number" min="0" step="any" id="total_inspected" name="total_inspected" value="{{ old('total_inspected', $report->total_inspected ?? '') }}" placeholder="0.00">@error('total_inspected')<div class="qrf-error">{{ $message }}</div>@enderror</div>
  <div class="qrf-field"><label for="total_passed">Total Passed</label><input type="number" min="0" step="any" id="total_passed" name="total_passed" value="{{ old('total_passed', $report->total_passed ?? '') }}" placeholder="0.00">@error('total_passed')<div class="qrf-error">{{ $message }}</div>@enderror</div>
  <div class="qrf-field"><label for="total_failed">Total Failed</label><input type="number" min="0" step="any" id="total_failed" name="total_failed" value="{{ old('total_failed', $report->total_failed ?? '') }}" placeholder="0.00">@error('total_failed')<div class="qrf-error">{{ $message }}</div>@enderror</div>
  <div class="qrf-field"><label for="pass_rate">Pass Rate (%)</label><input type="number" min="0" max="100" step="any" id="pass_rate" name="pass_rate" value="{{ old('pass_rate', $report->pass_rate ?? '') }}" placeholder="0.00"><div class="qrf-help">Automatically calculated from passed ÷ inspected; editable if needed.</div>@error('pass_rate')<div class="qrf-error">{{ $message }}</div>@enderror</div>
 </div><div class="qrf-summary"><div class="qrf-metric"><span>Inspected</span><strong data-qr-inspected>0</strong></div><div class="qrf-metric green"><span>Passed</span><strong data-qr-passed>0</strong></div><div class="qrf-metric red"><span>Failed</span><strong data-qr-failed>0</strong></div><div class="qrf-metric green"><span>Pass Rate</span><strong data-qr-rate>0%</strong></div></div><div class="qrf-progress"><span data-qr-progress></span></div><div class="qrf-warning" data-qr-warning>Passed and failed quantities exceed the total inspected quantity. Please review your values.</div></div></section>
</div>
<script>
(function(){
 const root=document.getElementById('quality-report-fields'); if(!root)return;
 const get=(id)=>root.querySelector('#'+id);
 const inspected=get('total_inspected'),passed=get('total_passed'),failed=get('total_failed'),rate=get('pass_rate');
 const fmt=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2});
 function update(autoRate){const i=Math.max(0,Number(inspected.value)||0),p=Math.max(0,Number(passed.value)||0),f=Math.max(0,Number(failed.value)||0),pct=i>0?p/i*100:0;
 root.querySelector('[data-qr-inspected]').textContent=fmt(i);root.querySelector('[data-qr-passed]').textContent=fmt(p);root.querySelector('[data-qr-failed]').textContent=fmt(f);root.querySelector('[data-qr-rate]').textContent=pct.toFixed(1)+'%';root.querySelector('[data-qr-progress]').style.width=Math.min(100,Math.max(0,pct))+'%';root.querySelector('[data-qr-warning]').style.display=p+f>i?'block':'none';if(autoRate)rate.value=pct.toFixed(2);
 }
 [inspected,passed,failed].forEach(el=>el.addEventListener('input',()=>update(true)));update(false);
})();
</script>
